<?php
if(session_status()===PHP_SESSION_NONE)session_start();require_once '../includes/config.php';require_once '../includes/database.php';require_once '../includes/auth.php';$db=new Database();$auth=new Auth($db);$auth->requireRole('passenger');$pdo=$db->getConnection();$stmt=$pdo->prepare("SELECT DISTINCT f.*,a.airline_name,oa.airport_name origin,da.airport_name destination FROM flights f JOIN baggage b ON b.flight_id=f.id JOIN airlines a ON f.airline_id=a.id JOIN airports oa ON f.origin_airport_id=oa.id JOIN airports da ON f.destination_airport_id=da.id WHERE b.passenger_id=? ORDER BY f.departure_time DESC");$stmt->execute([$auth->getUserId()]);$flights=$stmt->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Flight Info</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-5"><a href="dashboard.php">← Dashboard</a><h2>Flight Information</h2><div class="row g-3"><?php foreach($flights as $f):?><div class="col-md-6"><div class="card h-100"><div class="card-body"><h4><?=htmlspecialchars($f['flight_number'])?></h4><p><?=htmlspecialchars($f['airline_name'])?></p><p><?=htmlspecialchars($f['origin'])?> → <?=htmlspecialchars($f['destination'])?></p><p>Departure: <?=htmlspecialchars($f['departure_time'])?><br>Arrival: <?=htmlspecialchars($f['arrival_time'])?><br>Status: <strong><?=htmlspecialchars($f['status'])?></strong></p></div></div></div><?php endforeach;?></div></div></body></html>